DROP TABLE IF EXISTS `employees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `employees` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `companyId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `departmentId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designationId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `officeLocationId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shiftId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reportingManagerId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employeeCode` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `firstName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lastName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender` enum('MALE','FEMALE','OTHER') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dateOfBirth` date DEFAULT NULL,
  `joiningDate` date NOT NULL,
  `exitDate` date DEFAULT NULL,
  `employmentStatus` enum('FULL_TIME','PART_TIME','PROBATION','INTERN','CONTRACT','RESIGNED','TERMINATED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PROBATION',
  `emergencyContactName` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergencyContactPhone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergencyContactRelation` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `currentAddress` text COLLATE utf8mb4_unicode_ci,
  `permanentAddress` text COLLATE utf8mb4_unicode_ci,
  `bankName` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bankAccountNumber` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bankIfscCode` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `panNumber` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uanNumber` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pfNumber` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `esiNumber` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avatarUrl` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `workLocationType` enum('ON_SITE','OFF_SITE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ON_SITE',
  `employmentType` enum('OFFICE','FIELD') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OFFICE',
  PRIMARY KEY (`id`),
  UNIQUE KEY `employees_userId_key` (`userId`),
  UNIQUE KEY `employees_companyId_employeeCode_key` (`companyId`,`employeeCode`),
  KEY `employees_companyId_idx` (`companyId`),
  KEY `employees_departmentId_idx` (`departmentId`),
  KEY `employees_designationId_idx` (`designationId`),
  KEY `employees_officeLocationId_idx` (`officeLocationId`),
  KEY `employees_shiftId_idx` (`shiftId`),
  KEY `employees_reportingManagerId_idx` (`reportingManagerId`),
  CONSTRAINT `employees_companyId_fkey` FOREIGN KEY (`companyId`) REFERENCES `companies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `employees_departmentId_fkey` FOREIGN KEY (`departmentId`) REFERENCES `departments` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `employees_designationId_fkey` FOREIGN KEY (`designationId`) REFERENCES `designations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `employees_officeLocationId_fkey` FOREIGN KEY (`officeLocationId`) REFERENCES `office_locations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `employees_reportingManagerId_fkey` FOREIGN KEY (`reportingManagerId`) REFERENCES `employees` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `employees_shiftId_fkey` FOREIGN KEY (`shiftId`) REFERENCES `shifts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `employees_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

